// Chunk 19b: writes docs/blocks.md, one table row per shown block: the short player text, the stacking line and the full technical
// behaviour (BlockDef.desc, read at the block's fixed level or level 1). Run: npm run blocks-doc
import { writeFileSync } from 'fs';
import { pickerBlocks } from '../src/data/blocks';
import { blockText } from '../src/data/blockText';
import { describeBlock } from '../src/engine/compilerTypes';

const esc = (s: string) => s.replace(/\|/g, '\|');
const lines = [
  '# Blocks',
  '',
  'Generated by `npm run blocks-doc` (`scripts/blocks-doc.ts`); do not edit by hand. The short text and the stacking line are what the game shows (`src/data/blockText.ts`, at most 60 and 40 characters); the technical column is `BlockDef.desc` in `src/data/blocks.ts` at the block\'s fixed level (level 1 for blocks with upgrades).',
  '',
  '| Block | Short text | Stacking line | Technical behaviour |',
  '|---|---|---|---|',
];
for (const b of pickerBlocks()) {
  const lv = b.fixedLevel ?? 1;
  const t = blockText(b, lv);
  lines.push(`| ${b.name} | ${esc(t.short)} | ${t.stack ? esc(t.stack) : ''} | ${esc(describeBlock(b, lv))} |`);
}
writeFileSync('docs/blocks.md', lines.join('\n') + '\n');
console.log(`docs/blocks.md: ${pickerBlocks().length} blocks`);
